const $ = (s) => document.querySelector(s);
function localDateKey(date = new Date()){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;}
function normalizeDateKey(value){if(/^\d{4}-\d{2}-\d{2}$/.test(String(value||'')))return value;const parsed=new Date(value);return Number.isFinite(parsed.getTime())?localDateKey(parsed):localDateKey();}
const state = JSON.parse(localStorage.getItem('tomato-state') || '{}');
state.tasks ||= [{ id: Date.now(), text: '整理项目方案', done: false, pomodoros: 0 }, { id: Date.now() + 1, text: '阅读 20 页专业书', done: false, pomodoros: 0 }];
state.settings ||= { focus: 25, short: 5, long: 15, sunEvery: 1, sunEnabled: true, notifications: false, sunCadenceVersion: 2 };
if ((state.settings.sunCadenceVersion || 0) < 2) { state.settings.sunEvery = 1; state.settings.sunCadenceVersion = 2; } state.settings.sunEvery ||= 1; state.settings.sunEnabled ??= true; state.settings.notifications ??= false;
state.today ||= { date: new Date().toDateString(), pomodoros: 0, minutes: 0 }; state.history ||= {};
state.garden ||= {};
const legacyGardenUnits = (Number(state.garden.small) || 0) + (Number(state.garden.large) || 0) * 4 + (Number(state.garden.golden) || 0) * 16;
const legacySessions = Object.values(state.history).reduce((a,b)=>a+(Number(b)||0),0) + (Number(state.today.pomodoros)||0);
const legacyMinutes = Object.values(state.history).reduce((a,b)=>a+(Number(b)||0) * state.settings.focus,0) + (Number(state.today.minutes)||0);
state.focusStats ||= { totalFocusSessions: legacySessions, totalFocusMinutes: legacyMinutes };
state.focusStats.totalFocusSessions = Math.max(0, Number(state.focusStats.totalFocusSessions)||0);
state.focusStats.totalFocusMinutes = Math.max(0, Number(state.focusStats.totalFocusMinutes)||0);
if (!Number.isFinite(state.garden.currentPlantMinutes)) state.garden.currentPlantMinutes = (Number(state.garden.plantStage)||legacyGardenUnits%4) * 25;
state.garden.currentPlantMinutes = Math.max(0, Number(state.garden.currentPlantMinutes)||0);
state.garden.maturedTomatoes = Math.max(0, Number(state.garden.maturedTomatoes) || Number(state.garden.harvested) || Number(state.garden.matured) || Math.floor(legacyGardenUnits/4));
state.sessionCycle ||= { cycleCount: Number(state.cycles)||0, cycleDate: new Date().toDateString() };
state.sessionCycle.cycleDate = normalizeDateKey(state.sessionCycle.cycleDate);
if (state.sessionCycle.cycleDate !== localDateKey()) { state.sessionCycle.cycleCount = 0; state.sessionCycle.cycleDate = localDateKey(); }
state.sessionCycle.cycleCount = Math.max(0, Math.min(4, Number(state.sessionCycle.cycleCount)||0));
if (state.today.date !== new Date().toDateString()) state.today = { date: new Date().toDateString(), pomodoros: 0, minutes: 0 };
let mode = ['focus', 'short', 'long'].includes(state.activeMode) ? state.activeMode : 'focus';
let hasLocalTimerSnapshot = Number.isFinite(state.remaining);
let remaining = hasLocalTimerSnapshot ? state.remaining : state.settings[mode] * 60;
let running = false, timer, endAt = null, selectedId = state.selectedId || null, toastTimer, audioContext, noiseSource, ambientAudio, activeAmbient, alarmTimer, alarmTimeout, sunReminderTimer, alarmActive = false, pendingAlarmAction = null;
const circumference = 703.72;
function save(){Object.assign(state,{selectedId,activeMode:mode,remaining});state.cycles=state.sessionCycle.cycleCount;localStorage.setItem('tomato-state',JSON.stringify(state));hasLocalTimerSnapshot=true;}
function showToast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3000);}
function format(seconds){return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}
function modeName(){return {focus:'专注时间',short:'短暂休息',long:'长休息'}[mode];}
function setMode(next,fresh=true){clearInterval(timer);timer=null;running=false;endAt=null;mode=next;if(fresh)remaining=state.settings[mode]*60;document.querySelectorAll('.mode-tab').forEach(b=>{const on=b.dataset.mode===mode;b.classList.toggle('active',on);b.setAttribute('aria-selected',on)});renderTimer();save();}
function renderTimer(){const total=state.settings[mode]*60;const count=state.sessionCycle.cycleCount;$('#timeDisplay').textContent=format(Math.max(0,remaining));$('#modeLabel').textContent=running?modeName():remaining===total?'准备开始':'已暂停';$('#progressRing').style.strokeDashoffset=circumference*(1-Math.max(0,remaining)/total);$('#progressRing').style.stroke=mode==='focus'?'':'#9daa8a';$('#startButton').innerHTML=running?'<span>Ⅱ</span> 暂停':`<span>▶</span> ${mode==='focus'?'开始专注':'开始休息'}`;$('#cycleDots').textContent=Array.from({length:4},(_,i)=>i<count?'●':'○').join(' ');$('#cycleNoteText').textContent=count===4?'本轮完成，下一次为长休息':`再完成 ${4-count} 次专注，进入长休息`;document.title=running?`${format(remaining)} · ${modeName()} — 番茄钟`:'番茄钟 · 专注空间';}
function ensureAudio(){const C=window.AudioContext||window.webkitAudioContext;if(!C)return null;audioContext ||= new C();audioContext.resume();return audioContext;}
function ring(frequency=660,duration=.55){const context=ensureAudio();if(!context)return;const o=context.createOscillator(),g=context.createGain();o.frequency.value=frequency;g.gain.setValueAtTime(.1,context.currentTime);g.gain.exponentialRampToValueAtTime(.001,context.currentTime+duration);o.connect(g).connect(context.destination);o.start();o.stop(context.currentTime+duration);}
function notify(title,body){if(state.settings.notifications&&'Notification'in window&&Notification.permission==='granted')new Notification(title,{body});}
function growTomato(minutes){state.garden.currentPlantMinutes += minutes;while(state.garden.currentPlantMinutes>=100){state.garden.currentPlantMinutes-=100;state.garden.maturedTomatoes++;}}
function formatFocusTime(minutes){return minutes<60?`${minutes} 分钟`:`${Math.floor(minutes/60)} 小时${minutes%60?` ${minutes%60} 分钟`:''}`;}
function renderGarden(growing=false){const minutes=state.garden.currentPlantMinutes;const stage=minutes>=75?3:minutes>=50?2:minutes>=25?1:0;const plot=$('#gardenPlot');const src=['tomato-seed.svg','tomato-sprout.svg','tomato-plant.svg','tomato-tree.svg'][stage];const label=['种子','幼苗','大苗','小番茄'][stage];plot.innerHTML=`<div class="garden-soil"><img src="assets/${src}" alt="${label}"></div><div class="garden-soil empty"></div><div class="garden-soil empty"></div>`;plot.classList.toggle('growing',growing);$('#gardenTotal').textContent=`${state.garden.maturedTomatoes} 个`;$('#gardenTotalSessions').textContent=state.focusStats.totalFocusSessions;$('#gardenTotalTime').textContent=formatFocusTime(state.focusStats.totalFocusMinutes);$('#gardenTotalTomatoes').textContent=state.garden.maturedTomatoes;$('#gardenStageLabel').textContent=label;$('#gardenStageCount').textContent=`${minutes} / 100 分钟`;$('#growthMeter').innerHTML=''.padEnd(Math.min(10,Math.floor(minutes/10)),'■')+'□'.repeat(10-Math.min(10,Math.floor(minutes/10)));$('#gardenProgress').textContent=`当前植物：${minutes} / 100 分钟`;$('#harvestButton').classList.add('hidden');}
function shouldShowSunReminder(){return state.settings.sunEnabled&&state.sessionCycle.cycleCount%state.settings.sunEvery===0;}
function showSunReminder(){if(!shouldShowSunReminder())return;clearTimeout(sunReminderTimer);$('#sunModal').classList.remove('hidden');notify('护眼时间到了','离开屏幕，去窗边望向远处和自然光；请不要直视太阳。');sunReminderTimer=setTimeout(()=>$('#sunModal').classList.add('hidden'),10000);}
function startAlarm(title,message,afterStop=null){stopAlarm(false);alarmActive=true;pendingAlarmAction=afterStop;$('#alarmTitle').textContent=title;$('#alarmMessage').textContent=message;$('#alarmModal').classList.remove('hidden');const pulse=()=>ring(880,.6);pulse();alarmTimer=setInterval(pulse,1100);alarmTimeout=setTimeout(()=>stopAlarm(),10000);}
function stopAlarm(runAction=true){if(!alarmActive)return;clearInterval(alarmTimer);clearTimeout(alarmTimeout);alarmTimer=null;alarmTimeout=null;alarmActive=false;$('#alarmModal').classList.add('hidden');const action=pendingAlarmAction;pendingAlarmAction=null;if(runAction&&action)action();}
function finish(){const syncCore=mode==='focus'||mode==='long';clearInterval(timer);timer=null;running=false;endAt=null;remaining=0;if(mode==='focus'){state.sessionCycle.cycleCount=Math.min(4,state.sessionCycle.cycleCount+1);state.focusStats.totalFocusSessions++;state.focusStats.totalFocusMinutes+=state.settings.focus;state.today.pomodoros++;state.today.minutes+=state.settings.focus;growTomato(state.settings.focus);const key=new Date().toISOString().slice(0,10);state.history[key]=(state.history[key]||0)+1;const task=state.tasks.find(t=>t.id===selectedId);if(task)task.pomodoros++;const next=state.sessionCycle.cycleCount===4?'long':'short';setMode(next);const text='专注完成！植物按真实专注分钟成长。';showToast(text);notify('一个番茄完成',text);startAlarm('一个番茄完成','休息已经开始，提示音将在 10 秒后停止。',showSunReminder);toggleTimer();}else{if(mode==='long')state.sessionCycle.cycleCount=0;setMode('focus');showToast('休息结束，准备开始新一轮专注。');notify('休息结束','可以开始下一轮专注了。');startAlarm('休息结束','请点击“开始专注”进入下一轮。');}save();if(syncCore)queueCloudSync();renderTimer();renderCurrent();renderGarden(true);renderTasks();renderStats();}
function syncTimer(){if(!running||!endAt)return;const next=Math.max(0,Math.ceil((endAt-Date.now())/1000));if(next<=0){finish();return;}if(next!==remaining){remaining=next;save();}renderTimer();}
function toggleTimer(){if(running){syncTimer();clearInterval(timer);timer=null;running=false;endAt=null;}else{ensureAudio();running=true;endAt=Date.now()+remaining*1000;syncTimer();timer=setInterval(syncTimer,250);}renderTimer();save();}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)syncTimer();});
function escapeHtml(value){const d=document.createElement('div');d.textContent=value;return d.innerHTML;}
function renderTasks(){const box=$('#taskList');box.innerHTML='';state.tasks.forEach(task=>{const item=document.createElement('div');item.className='task'+(task.done?' done':'');item.innerHTML=`<input class="check" aria-label="完成${escapeHtml(task.text)}" type="checkbox" ${task.done?'checked':''}><span class="task-name">${escapeHtml(task.text)}</span><span class="task-count">${task.pomodoros} 个番茄</span><button class="choose">${selectedId===task.id?'已选择':'专注此项'}</button><button class="delete" title="删除${escapeHtml(task.text)}">×</button>`;item.querySelector('.check').onchange=()=>{task.done=!task.done;save();renderTasks();renderStats()};item.querySelector('.choose').onclick=()=>{selectedId=task.id;save();renderCurrent();renderTasks();showView('focus')};item.querySelector('.delete').onclick=()=>{state.tasks=state.tasks.filter(t=>t.id!==task.id);if(selectedId===task.id)selectedId=null;save();renderTasks();renderCurrent()};box.append(item)});}
function renderCurrent(){const task=state.tasks.find(t=>t.id===selectedId);$('#currentTaskText').textContent=task?task.text:'选择一项待办，开始专注';$('#todayFocus').textContent=state.today.pomodoros;$('#todayMinutes').textContent=state.today.minutes;}
function renderStats(){$('#summaryPomodoros').textContent=state.focusStats.totalFocusSessions;$('#summaryMinutes').textContent=state.focusStats.totalFocusMinutes;$('#summaryMatured').textContent=state.garden.maturedTomatoes;const chart=$('#barChart'),labels=$('#chartLabels');chart.innerHTML='';labels.innerHTML='';const days=[];for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const key=d.toISOString().slice(0,10);days.push({label:['日','一','二','三','四','五','六'][d.getDay()],value:i===0?state.today.pomodoros:(state.history[key]||0)})}const max=Math.max(1,...days.map(d=>d.value));days.forEach((d,i)=>{const bar=document.createElement('div');bar.className='bar'+(i===6?' today':'');bar.style.height=`${Math.max(5,d.value/max*100)}%`;bar.title=`${d.value} 次专注`;chart.append(bar);const label=document.createElement('span');label.textContent=`周${d.label}`;labels.append(label)});}
function renderSunSetting(){$('#sunEvery').textContent=state.settings.sunEvery;const button=$('#sunToggle');button.textContent=state.settings.sunEnabled?'已开启':'已暂停';button.classList.toggle('off',!state.settings.sunEnabled);button.setAttribute('aria-pressed',String(state.settings.sunEnabled));}
function showView(view){document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));$(`#${view}View`).classList.add('active');document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===view));$('#viewTitle').textContent={focus:'专注片刻',tasks:'待办清单',stats:'专注记录'}[view];}
const ambientTracks={rain:{label:'细雨',icon:'☂',url:'https://assets.mixkit.co/active_storage/sfx/2393/2393-preview.mp3'},waves:{label:'海浪',icon:'〰',url:'https://assets.mixkit.co/active_storage/sfx/1185/1185-preview.mp3'},cafe:{label:'咖啡馆',icon:'♨',url:'https://assets.mixkit.co/active_storage/sfx/444/444-preview.mp3'},birds:{label:'晨鸟',icon:'♩',url:'https://assets.mixkit.co/active_storage/sfx/2472/2472-preview.mp3'},white:{label:'白噪音',icon:'∿'}};
function resetSoundButtons(){document.querySelectorAll('.sound').forEach(button=>{const track=ambientTracks[button.dataset.sound];button.classList.remove('active');button.textContent=`${track.icon} ${track.label}`;});}
function stopAmbient(){if(ambientAudio){ambientAudio.pause();ambientAudio.src='';ambientAudio=null;}if(noiseSource){noiseSource.stop();noiseSource.disconnect();noiseSource=null;}activeAmbient=null;resetSoundButtons();}
function startWhiteNoise(){const context=ensureAudio();if(!context){showToast('当前浏览器不支持播放环境音');return false;}const buffer=context.createBuffer(1,context.sampleRate*2,context.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;noiseSource=context.createBufferSource();noiseSource.buffer=buffer;noiseSource.loop=true;const gain=context.createGain();gain.gain.value=.055;noiseSource.connect(gain).connect(context.destination);noiseSource.start();return true;}
function toggleAmbient(button){const key=button.dataset.sound,track=ambientTracks[key];if(activeAmbient===key){stopAmbient();showToast(`${track.label}已暂停`);return;}stopAmbient();if(key==='white'){if(!startWhiteNoise())return;}else{ambientAudio=new Audio(track.url);ambientAudio.loop=true;ambientAudio.volume=.28;ambientAudio.play().catch(()=>{stopAmbient();showToast('音频加载失败，请检查网络后重试。');});}activeAmbient=key;button.classList.add('active');button.textContent=`${track.icon} ${track.label} · 播放中`;showToast(`${track.label}正在播放`);}
$('#dateLabel').textContent=new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long'}).format(new Date());
document.querySelectorAll('.nav-item').forEach(b=>b.onclick=()=>showView(b.dataset.view));document.querySelectorAll('.mode-tab').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));
