$('#startButton').onclick=()=>toggleTimer();$('#resetButton').onclick=()=>setMode(mode);$('#selectTaskButton').onclick=()=>showView('tasks');
$('#cycleResetButton').onclick=()=>{state.sessionCycle.cycleCount=0;state.sessionCycle.cycleDate=localDateKey();save();queueCloudSync();renderTimer();showToast('本轮进度已清零，长期统计和番茄园未改变。');};
$('#harvestButton').onclick=()=>harvestMatureTomato();
$('#addTaskButton').onclick=()=>{$('#taskForm').classList.toggle('hidden');$('#taskInput').focus();};$('#taskForm').onsubmit=e=>{e.preventDefault();const text=$('#taskInput').value.trim();if(!text)return;state.tasks.unshift({id:Date.now(),text,done:false,pomodoros:0});$('#taskInput').value='';$('#taskForm').classList.add('hidden');save();renderTasks();};
document.querySelectorAll('.sound').forEach(button=>button.onclick=()=>toggleAmbient(button));
$('#fullscreenButton').onclick=()=>setFocusScreen(!document.body.classList.contains('focus-screen'));$('#exitFocusButton').onclick=()=>setFocusScreen(false);$('#sunToggle').onclick=()=>{state.settings.sunEnabled=!state.settings.sunEnabled;save();renderSunSetting();showToast(state.settings.sunEnabled?'护眼提醒已开启':'护眼提醒已暂停');};
$('#settingsButton').onclick=()=>{$('#focusInput').value=state.settings.focus;$('#shortInput').value=state.settings.short;$('#longInput').value=state.settings.long;$('#sunInput').value=state.settings.sunEvery;$('#notificationInput').checked=state.settings.notifications;$('#settingsModal').classList.remove('hidden');};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(`#${b.dataset.close}`).classList.add('hidden'));$('#sunDoneButton').onclick=()=>{clearTimeout(sunReminderTimer);$('#sunModal').classList.add('hidden');};$('#stopAlarmButton').onclick=()=>stopAlarm();
$('#settingsForm').onsubmit=async e=>{e.preventDefault();const values={focus:+$('#focusInput').value,short:+$('#shortInput').value,long:+$('#longInput').value,sunEvery:+$('#sunInput').value};if(Object.values(values).some(v=>!Number.isFinite(v)||v<1))return showToast('请输入大于 0 的分钟数。');if($('#notificationInput').checked&&'Notification'in window&&Notification.permission==='default'){const permission=await Notification.requestPermission();state.settings.notifications=permission==='granted';if(permission!=='granted')showToast('浏览器通知未授权，仍会在页面内提醒。');}else state.settings.notifications=$('#notificationInput').checked&&('Notification'in window)&&Notification.permission==='granted';Object.assign(state.settings,values);setMode(mode);save();queueCloudSync();renderSunSetting();$('#settingsModal').classList.add('hidden');showToast('你的专注节奏已保存。');};
document.addEventListener('keydown',e=>{if(e.code==='Space'&&!['INPUT','TEXTAREA','BUTTON'].includes(document.activeElement.tagName)&&!document.querySelector('.modal:not(.hidden)')){e.preventDefault();toggleTimer();}if(e.key==='Escape'){if(document.body.classList.contains('focus-screen'))setFocusScreen(false);if(!alarmActive)document.querySelectorAll('.modal').forEach(m=>m.classList.add('hidden'));}});
const syncQueueKey='tomato-state-sync-queue',localOwnerKey='tomato-state-owner';
let authClient=null,authMode='login',activeAuthUser=null,syncStatusText='',syncPromise=null,syncPromiseUserId=null,cloudSyncTimer=null,cloudSyncRetryTimer=null;
function authError(error){$('#authError').textContent=error?.message||'操作失败，请稍后重试。';}
function renderAuth(user){const name=user?(user.email||'账号').split('@')[0]:'';$('#accountMessage').textContent=user?`你好，${name} · ${syncStatusText||'云端同步中'}`:'登录后同步你的番茄园';$('#accountButton').textContent=user?'退出登录':'登录 / 注册';$('#accountButton').dataset.action=user?'logout':'open';}
function setCloudStatus(message){syncStatusText=message;if(activeAuthUser){const name=(activeAuthUser.email||'账号').split('@')[0];$('#accountMessage').textContent=`你好，${name} · ${message}`;}}
function clearCloudRetry(){clearTimeout(cloudSyncRetryTimer);cloudSyncRetryTimer=null;}
function scheduleCloudRetry(userId){clearCloudRetry();cloudSyncRetryTimer=setTimeout(()=>{cloudSyncRetryTimer=null;if(activeAuthUser?.id===userId)void loadCloudState(activeAuthUser);},15000);}
function readSyncQueue(){try{return JSON.parse(localStorage.getItem(syncQueueKey)||'{}')||{};}catch{return {};}}
function localCoreSnapshot(){return{total_focus_sessions:state.focusStats.totalFocusSessions,total_focus_minutes:state.focusStats.totalFocusMinutes,cycle_count:state.sessionCycle.cycleCount,cycle_date:normalizeDateKey(state.sessionCycle.cycleDate),current_plant_minutes:state.garden.currentPlantMinutes,matured_tomatoes:state.garden.maturedTomatoes,settings:{focus:state.settings.focus,short:state.settings.short,long:state.settings.long}};}
function savePendingSnapshot(userId){const queue=readSyncQueue(),pending={updated_at:new Date().toISOString(),data:localCoreSnapshot()};queue[userId]=pending;try{localStorage.setItem(syncQueueKey,JSON.stringify(queue));}catch{}return pending;}
function clearPendingSnapshot(userId,updatedAt){const queue=readSyncQueue(),pending=queue[userId];if(!pending||pending.updated_at!==updatedAt)return;delete queue[userId];try{localStorage.setItem(syncQueueKey,JSON.stringify(queue));}catch{}}
function pendingIsNewer(pending,row){return!!pending&&Number.isFinite(Date.parse(pending.updated_at))&&Date.parse(pending.updated_at)>Date.parse(row?.updated_at||'');}
function applyCoreSnapshot(data){state.focusStats.totalFocusSessions=Math.max(0,Number(data.total_focus_sessions)||0);state.focusStats.totalFocusMinutes=Math.max(0,Number(data.total_focus_minutes)||0);state.sessionCycle={cycleCount:Math.max(0,Math.min(4,Number(data.cycle_count)||0)),cycleDate:normalizeDateKey(data.cycle_date)};state.garden.currentPlantMinutes=Math.max(0,Number(data.current_plant_minutes)||0);state.garden.maturedTomatoes=Math.max(0,Number(data.matured_tomatoes)||0);const settings=data.settings||{};for(const key of ['focus','short','long']){const value=Number(settings[key]);if(Number.isFinite(value)&&value>0)state.settings[key]=value;}const expired=state.sessionCycle.cycleDate!==localDateKey();if(expired){state.sessionCycle.cycleCount=0;state.sessionCycle.cycleDate=localDateKey();}state.cycles=state.sessionCycle.cycleCount;return expired;}
function resetCoreForNewAccount(){state.focusStats={totalFocusSessions:0,totalFocusMinutes:0};state.sessionCycle={cycleCount:0,cycleDate:localDateKey()};state.cycles=0;state.garden.currentPlantMinutes=0;state.garden.maturedTomatoes=0;Object.assign(state.settings,{focus:25,short:5,long:15});save();}
function renderSyncedCore(){if(!hasLocalTimerSnapshot)remaining=state.settings[mode]*60;save();renderTimer();renderCurrent();renderGarden();renderStats();renderSunSetting();}
function cloudRow(userId,pending){return{user_id:userId,...pending.data,updated_at:pending.updated_at};}
async function uploadPendingSnapshot(userId,pending){if(!authClient||activeAuthUser?.id!==userId)return;const{error}=await authClient.from('user_state').upsert(cloudRow(userId,pending),{onConflict:'user_id'});if(activeAuthUser?.id!==userId)return;if(error){setCloudStatus('离线缓存，稍后重试');scheduleCloudRetry(userId);return;}clearCloudRetry();clearPendingSnapshot(userId,pending.updated_at);setCloudStatus('已同步');}
function queueCloudSync(){const userId=activeAuthUser?.id;if(!userId||!authClient)return;const pending=savePendingSnapshot(userId);setCloudStatus('等待同步');clearTimeout(cloudSyncTimer);cloudSyncTimer=setTimeout(()=>void uploadPendingSnapshot(userId,pending),350);}
async function loadCloudState(user){if(!authClient||!user?.id)return;if(syncPromise&&syncPromiseUserId===user.id)return syncPromise;syncPromiseUserId=user.id;syncPromise=(async()=>{const userId=user.id;const priorOwner=localStorage.getItem(localOwnerKey);if(priorOwner&&priorOwner!==userId){resetCoreForNewAccount();localStorage.setItem(localOwnerKey,userId);}setCloudStatus('正在读取云端');const{data:row,error}=await authClient.from('user_state').select('user_id,total_focus_sessions,total_focus_minutes,cycle_count,cycle_date,current_plant_minutes,matured_tomatoes,settings,updated_at').eq('user_id',userId).maybeSingle();if(activeAuthUser?.id!==userId)return;if(error){setCloudStatus('离线缓存，联网后重试');scheduleCloudRetry(userId);return;}clearCloudRetry();const pending=readSyncQueue()[userId];if(row){localStorage.setItem(localOwnerKey,userId);if(pendingIsNewer(pending,row)){const cycleExpired=applyCoreSnapshot(pending.data);renderSyncedCore();if(cycleExpired){const resetPending=savePendingSnapshot(userId);await uploadPendingSnapshot(userId,resetPending);}else await uploadPendingSnapshot(userId,pending);}else{clearPendingSnapshot(userId,pending?.updated_at);const cycleExpired=applyCoreSnapshot(row);renderSyncedCore();setCloudStatus('已同步');if(cycleExpired)queueCloudSync();}return;}if(pending){const cycleExpired=applyCoreSnapshot(pending.data);localStorage.setItem(localOwnerKey,userId);renderSyncedCore();await uploadPendingSnapshot(userId,cycleExpired?savePendingSnapshot(userId):pending);return;}const owner=localStorage.getItem(localOwnerKey);if(!owner||owner===userId){const migration=savePendingSnapshot(userId);localStorage.setItem(localOwnerKey,userId);await uploadPendingSnapshot(userId,migration);return;}setCloudStatus('本地数据已保留');})().catch(()=>{setCloudStatus('离线缓存，联网后重试');scheduleCloudRetry(user.id);}).finally(()=>{if(syncPromiseUserId===user.id){syncPromise=null;syncPromiseUserId=null;}});return syncPromise;}
function handleAuthSession(user){const previousId=activeAuthUser?.id||null;activeAuthUser=user||null;if(!user){clearTimeout(cloudSyncTimer);clearCloudRetry();syncStatusText='';renderAuth(null);return;}if(previousId!==user.id){clearCloudRetry();syncStatusText='正在连接云端';}renderAuth(user);void loadCloudState(user);}
function setAuthMode(mode){authMode=mode;$('#authTitle').textContent=mode==='login'?'登录你的番茄园':'创建番茄账号';$('#authSubmit').textContent=mode==='login'?'登录':'注册';$('#authSwitch').textContent=mode==='login'?'没有账号？注册':'已有账号？登录';$('#authError').textContent='';}
async function initAuth(){const config=window.SUPABASE_CONFIG;if(!config?.url||!config?.anonKey||config.url.includes('YOUR_PROJECT')||!window.supabase?.createClient)return;authClient=window.supabase.createClient(config.url,config.anonKey);try{const{data}=await authClient.auth.getSession();handleAuthSession(data.session?.user||null);authClient.auth.onAuthStateChange((_event,session)=>{const user=session?.user||null;setTimeout(()=>handleAuthSession(user),0);});}catch{setCloudStatus('离线模式，本地数据可用');}}
window.addEventListener('online',()=>{if(activeAuthUser){clearCloudRetry();void loadCloudState(activeAuthUser);}});
$('#accountButton').onclick=async()=>{if(!authClient)return showToast('请先配置 Supabase 账号服务。');if($('#accountButton').dataset.action==='logout'){const{error}=await authClient.auth.signOut();if(error)showToast(error.message);else{handleAuthSession(null);showToast('已退出登录。');}return;}setAuthMode('login');$('#authModal').classList.remove('hidden');$('#authEmail').focus();};
$('#authSwitch').onclick=()=>setAuthMode(authMode==='login'?'signup':'login');
$('#authForm').onsubmit=async e=>{e.preventDefault();const email=$('#authEmail').value.trim(),password=$('#authPassword').value;const result=authMode==='login'?await authClient.auth.signInWithPassword({email,password}):await authClient.auth.signUp({email,password});if(result.error)return authError(result.error);$('#authModal').classList.add('hidden');showToast(authMode==='signup'&&!result.data.session?'注册成功，请检查邮箱完成验证。':authMode==='login'?'登录成功。':'注册成功。');};
renderTimer();renderTasks();renderCurrent();renderGarden();renderStats();renderSunSetting();initAuth();
